INSERT INTO academy_field_activities(number,outcome,demonstration,verification) VALUES
  (1, 'A sequence you can repeat after watching it', 'Ask someone to fold a paper envelope while you watch the order of their movements.', 'Use a second sheet to repeat the sequence. Compare which folds align and ask for a replay of any step you missed.'),
  (2, 'An outline made with a tool that fits your grip', 'Compare the grip on two pencils or crayon holders. Pick one you can hold loosely and steer.', 'Trace the same shape with both tools. Compare the marks and explain which grip let you follow the edge more closely.'),
  (3, 'A freestanding paper card', 'Watch someone fold a sheet into a standing tent without speaking. Notice where their thumbs hold the fold.', 'Repeat the fold. Compare whether both tents stay upright after one gentle puff of air, then show the motion without speaking.'),
  (4, 'A paper bridge that holds three coins', 'Place the finished bridge on two books and put three coins on it. Turn it over to inspect the folds.', 'Fold a sheet into an accordion and span the same gap. Test one coin at a time and compare with a flat sheet.'),
  (5, 'A project chosen when you are ready', 'Set out three sample projects: a paper tent, a paper weaving, and a pebble pattern. Choose one to inspect.', 'Try it when you’re ready. Revisit a second project later and record what made you want to start it.'),
  (6, 'A load that stays balanced', 'Place a ruler on a pencil. Watch which way it tips with one counter on one end.', 'Move the counter or add another counter on the other side. Predict the next movement before you test it.'),
  (7, 'A game a new player can join and teach', 'An experienced player shows a learner how to play a simple matching game by playing the first round together.', 'Swap roles. Let the new player teach the rules to a third person and note which rule needed a demonstration.'),
  (8, 'An exploration with a boundary you can point to', 'Mark a clear practice area with removable paper markers. Walk the perimeter with the person supervising the activity.', 'Choose three things to observe inside the area. Retell where to stop and what to do when something interesting lies beyond the boundary.'),
  (9, 'A record of what really moved', 'Sit in a familiar, supervised spot and quietly watch a plant, a patch of sky, or a window for five minutes.', 'Sketch or write three changes. Mark whether you saw each change directly or inferred it from sound or movement elsewhere.'),
  (10, 'A household job completed from start to finish', 'Show the finished arrangement of a small set of books or classroom supplies.', 'Let the learner put everything back after use. Compare the result with the example and let the learner explain how they knew the job was done.'),
  (11, 'A tabletop structure that survives a repeat test', 'Look at a short paper bridge holding a single coin between two books.', 'Build two bridges from identical paper. Change one fold at a time and compare the number of coins each one holds.'),
  (12, 'A simple problem solved with only the help you request', 'Make a loose shoelace puzzle on a table and show the desired end state with a second lace.', 'Let the learner decide when to ask for one hint. Reset it and have them demonstrate the move that freed the lace.'),
  (13, 'A useful object made from scraps', 'Show a pencil rest folded from scrap cardstock. Inspect where the folds stop it from flattening.', 'Use cardboard scraps to build a rest that holds two pencils. Compare designs and save scraps that could be used again.'),
  (14, 'A hand movement reproduced by observation', 'Place two sheets side by side. Watch where a partner places their fingers as they crease a sheet.', 'Mirror the motion on your sheet. Compare the two creases and switch roles for another fold.'),
  (15, 'A route you can follow and explain', 'Set three checkpoints in a familiar supervised room or yard and show the destination before starting.', 'Follow the checkpoints in order, retrace the route, and draw a simple map someone else can use.'),
  (21, 'One proverb you can test', 'Read “Measure twice, cut once.” Decide what measuring twice is supposed to prevent.', 'Use two strips of paper. Mark a target length once on the first strip and check the second strip twice. Tear along each mark and compare both strips against the target.'),
  (46, 'Two piles combined into one total', 'Put two pebbles in the left space and three in the right space. Move them into the middle one at a time as you count.', 'Draw three circles on paper for the two starting piles and the total. Build a second example with different counts and tell someone how you checked the result.'),
  (59, 'A folded paper shape that stands on its own', 'Look at a folded accordion standing on its long edge. Count the peaks and valleys from one end.', 'Fold two identical sheets, one into an accordion and one just down the center. Stand both on a flat surface and compare what happens when you gently nudge them.'),
  (65, 'A small woven square with alternating rows', 'Turn over a sample of paper weaving. Trace one strip across the page and say where it passes over and under.', 'Lay four paper strips on the table. Weave a fifth strip over and under. Start the next row the opposite way. Tug one loose edge, repair it, and explain why the alternating pattern matters.'),
  (92, 'Two shares made by one person and chosen by another', 'Give two players eight paper tokens. One player makes two shares and the other chooses first.', 'Ask each player what made the result fair. Swap roles and repeat with an odd number of tokens. Compare the new shares and agree on a rule for the extra token.'),
  (101, 'A finished object the learner can build and teach', 'Choose one Workbench field activity. Show the finished result and explain the check you used to see whether it worked.', 'Rebuild it from the starting materials, then teach another person the steps. Record what they could reproduce and one place where the explanation needed to be clearer.')
